const spellsPHB = [
    { name: "Волшебная рука", level: 0, classes: ["Бард", "Волшебник", "Чародей", "Колдун", "Изобретатель"], desc: "Создает призрачную руку, способную переносить предметы до 10 фунтов на расстоянии 30 фт." },
    { name: "Верное нанесение удара", level: 0, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "Концентрация. Дает преимущество на следующий бросок атаки по цели в вашем следующем ходу." },
    { name: "Друидическое искусство", level: 0, classes: ["Друид"], desc: "Предсказание погоды, мгновенное распускание цветка или создание слабого ветерка." },
    { name: "Кнут шипов", level: 0, classes: ["Друид", "Изобретатель"], desc: "Атака заклинанием ближнего боя (до 30 фт). При попадании 1d6 колющего урона, и цель подтягивается к вам на 10 фт." },
    { name: "Дубинка (Шиллела)", level: 0, classes: ["Друид"], desc: "Бонусное. Ваша дубинка или посох становится магическим, наносит 1d8 урона, и вы используете Мудрость для атак." },
    { name: "Злая насмешка", level: 0, classes: ["Бард"], desc: "Спасбросок Мудрости или цель получает 1d4 психического урона и помеху на следующую атаку." },
    { name: "Луч холода", level: 0, classes: ["Волшебник", "Чародей", "Изобретатель"], desc: "Дальняя атака. 1d8 урона холодом, скорость цели снижается на 10 фт." },
    { name: "Малая иллюзия", level: 0, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "Создает обманчивый звук или образ объекта в пределах куба 5 фт." },
    { name: "Мистический заряд", level: 0, classes: ["Колдун"], desc: "Дальняя атака. Урон 1d10 силой. Создает больше лучей на высоких уровнях." },
    { name: "Огненный снаряд", level: 0, classes: ["Волшебник", "Чародей", "Изобретатель"], desc: "Дальняя атака. Урон 1d10 огнем." },
    { name: "Починка", level: 0, classes: ["Бард", "Жрец", "Друид", "Волшебник", "Чародей", "Изобретатель"], desc: "Исправляет одно повреждение или разрыв на предмете (до 1 фута)." },
    { name: "Свет", level: 0, classes: ["Бард", "Жрец", "Волшебник", "Чародей", "Изобретатель"], desc: "Предмет начинает испускать яркий свет в радиусе 20 фт и тусклый еще на 20 фт." },
    { name: "Священное пламя", level: 0, classes: ["Жрец", "Изобретатель"], desc: "Спасбросок Ловкости (игнорирует укрытия). Урон 1d8 излучением." },
    { name: "Сопротивление", level: 0, classes: ["Жрец", "Друид", "Изобретатель"], desc: "Концентрация. Касание. Цель добавляет 1d4 к одному спасброску по своему выбору." },
    { name: "Указание", level: 0, classes: ["Жрец", "Друид", "Изобретатель"], desc: "Концентрация. Цель добавляет 1d4 к одной проверке характеристики." },
    { name: "Фокусы", level: 0, classes: ["Бард", "Волшебник", "Чародей", "Колдун", "Изобретатель"], desc: "Мелкие магические трюки: зажечь свечу, очистить одежду, создать искры." },
    { name: "Чудотворство", level: 0, classes: ["Жрец"], desc: "Проявление сверхъестественного: громкий голос, дрожание земли, изменение цвета глаз." },
    { name: "Шоковая хватка", level: 0, classes: ["Волшебник", "Чародей"], desc: "Атака касанием (преимущество по металлической броне). 1d8 молнией, цель теряет реакции." },
    { name: "Ядовитые брызги", level: 0, classes: ["Друид", "Волшебник", "Чародей", "Колдун", "Изобретатель"], desc: "Спасбросок Телосложения (10 фт). Урон 1d12 ядом." }
    , { name: "Леденящее прикосновение", level: 0, classes: ["Волшебник", "Колдун", "Чародей", "Изобретатель"], desc: "Дальняя атака (120 фт). 1d8 некротического урона, цель не может лечиться до вашего следующего хода." }
    , { name: "Безмолвный образ", level: 1, classes: ["Бард", "Волшебник", "Чародей"], desc: "Концентрация. Создает визуальную иллюзию существа или предмета в пределах куба с ребромы 15 фт." },
    { name: "Благословение", level: 1, classes: ["Жрец", "Паладин"], desc: "Концентрация. До 3 выбранных существ добавляют 1d4 к своим броскам атаки и спасброскам." },
    { name: "Ведьмин снаряд", level: 1, classes: ["Волшебник", "Чародей", "Колдун"], desc: "Концентрация. Дистанционная атака: 1d12 урона молнией. Каждый ход можно автоматически наносить еще 1d12 урона действием." },
    { name: "Волшебная стрела", level: 1, classes: ["Волшебник", "Чародей", "Изобретатель"], desc: "Создает 3 дротика, каждый наносит 1d4+1 урона силой. Автоматическое попадание по цели." },
    { name: "Героизм", level: 1, classes: ["Бард", "Паладин"], desc: "Концентрация. Касание. Цель получает иммунитет к испугу и временные хиты в размере вашего мод. магии каждый ход." },
    { name: "Громовая волна", level: 1, classes: ["Бард", "Друид", "Волшебник", "Чародей", "Изобретатель"], desc: "Куб 15 фт. Спас Телосложения. 2d8 урона звуком, цели отталкиваются на 10 фт. и падают ничком." },
    { name: "Сглаз", level: 1, classes: ["Колдун", "Изобретатель"], desc: "Бонусное. Концентрация. Доп. 1d6 некротикой при попадании. Цель получает помеху на проверки одного выбранного стата." },
    { name: "Доспехи мага", level: 1, classes: ["Волшебник", "Чародей"], desc: "КД цели без доспехов становится равен 13 + модификатор Ловкости. Длится 8 часов." },
    { name: "Лечение ран", level: 1, classes: ["Бард", "Жрец", "Друид", "Паладин", "Следопыт", "Изобретатель"], desc: "Касание. Восстанавливает хиты в размере 1d8 + мод. магии." },
    { name: "Ложная жизнь", level: 1, classes: ["Волшебник", "Чародей", "Изобретатель"], desc: "Вы черпаете некротическую энергию и получаете 1d4 + 4 временных хитов на 1 час." },
    { name: "Палящая кара", level: 1, classes: ["Паладин"], desc: "Бонусное. Концентрация. Следующий удар оружием наносит доп. 1d6 урона излучением, и цель начинает светиться (преимущество на атаки по ней)." },
    { name: "Маскировка", level: 1, classes: ["Бард", "Волшебник", "Чародей", "Изобретатель"], desc: "Вы полностью меняете свой внешний вид (рост до 1 фута, расу, одежду, голос) на 1 час." },
    { name: "Метка охотника", level: 1, classes: ["Следопыт"], desc: "Бонусное. Концентрация. Ваши атаки оружием наносят отмеченной цели дополнительные 1d6 колющего урона." },
    { name: "Направляющий снаряд", level: 1, classes: ["Жрец"], desc: "Дальняя атака заклинанием. Наносит 4d6 урона излучением. Следующая атака по этой цели совершается с преимуществом." },
    { name: "Невидимое письмо", level: 1, classes: ["Бард", "Волшебник"], desc: "Вы пишете текст на поверхности, который становится невидимым для всех, кроме вас и указанных вами существ." },
    { name: "Обнаружение зла и добра", level: 1, classes: ["Жрец", "Паладин"], desc: "Концентрация. Вы узнаете, есть ли в пределах 30 фт исчадия, небожители, феи, нежить, элементали или десницы." },
    { name: "Обнаружение магии", level: 1, classes: ["Бард", "Жрец", "Друид", "Паладин", "Следопыт", "Волшебник", "Чародей", "Изобретатель"], desc: "Концентрация. Вы чувствуете присутствие магии в пределах 30 фт и видите ауру вокруг магических объектов." },
    { name: "Обнаружение яда и болезней", level: 1, classes: ["Жрец", "Друид", "Паладин", "Следопыт"], desc: "Концентрация. Вы чувствуете присутствие, тип и происхождение ядов, ядовитых существ и болезней в пределах 30 фт." },
    { name: "Пылающие руки", level: 1, classes: ["Волшебник", "Чародей", "Изобретатель"], desc: "Конус 15 фт. Спас Ловкости. 3d6 урона огнем (половина при успехе). Поджигает горючие предметы." },
    { name: "Опознание", level: 1, classes: ["Бард", "Волшебник", "Изобретатель"], desc: "Ритуал. Касание. Вы узнаете все магические свойства предмета, его заряды и наложенные на него заклинания." },
    { name: "Опутывание", level: 1, classes: ["Друид"], desc: "Концентрация. Квадрат 20 фт. Спас Силы или все существа в зоне становятся опутанными жесткими растениями." },
    { name: "Очарование личности", level: 1, classes: ["Бард", "Друид", "Волшебник", "Чародей", "Колдун"], desc: "Спас Мудрости. Гуманоид становится очарованным вами на 1 час и считает вас дружелюбным знакомым." },
    { name: "Очищение пищи и питья", level: 1, classes: ["Жрец", "Друид", "Изобретатель"], desc: "Ритуал. Вся немагическая еда и питье в радиусе 5 фт очищаются от любых ядов, токсинов и гнили." },
    { name: "Падение перышком", level: 1, classes: ["Бард", "Волшебник", "Чародей"], desc: "Реакция. До 5 падающих существ замедляют скорость падения до 10 фт в секунду и не получают урона при приземлении." },
    { name: "Убежище", level: 1, classes: ["Жрец", "Изобретатель"], desc: "Вы защищаете существо. Любой, кто пытается атаковать цель, должен сначала пройти спас Мудрости, иначе атака тратится впустую." },
    { name: "Понимание языков", level: 1, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "Ритуал. Вы начинаете понимать буквальный смысл любого услышанного или прочитанного языка в течение 1 часа." },
    { name: "Поспешное отступление", level: 1, classes: ["Волшебник", "Чародей", "Колдун", "Изобретатель"], desc: "Концентрация. Вы можете совершать действие Рывок в качестве бонусного действия каждый ход." },
    { name: "Приказ", level: 1, classes: ["Жрец", "Паладин"], desc: "Спас Мудрости. Вы заставляете цель выполнить одну команду из одного слова ('Упади', 'Брось', 'Беги', 'Замри') в её следующий ход." },
    { name: "Погибель", level: 1, classes: ["Бард", "Жрец"], desc: "Концентрация. До 3 выбранных существ вычитают 1d4 из всех своих бросков атаки и спасбросков." },
    { name: "Прыжок", level: 1, classes: ["Друид", "Следопыт", "Волшебник", "Чародей", "Изобретатель"], desc: "Касание. Дальность прыжков существа утраивается на 1 минуту." },
    { name: "Разговор с животными", level: 1, classes: ["Бард", "Друид", "Следопыт"], desc: "Ритуал. Вы получаете возможность вербально общаться со зверями, узнавать их мысли и просить о простых услугах на 1 час." },
    { name: "Скороход", level: 1, classes: ["Бард", "Друид", "Следопыт", "Волшебник", "Изобретатель"], desc: "Касание. Базовая скорость цели увеличивается на 10 фт. Эффект длится 1 час." },
    { name: "Диссонирующий шепот", level: 1, classes: ["Бард"], desc: "Вы создаете пугающий или манящий призрачный шепот, слышимый только одной выбранной цели в пределах 30 фт." },
    { name: "Слово исцеления", level: 1, classes: ["Бард", "Жрец", "Друид"], desc: "Бонусное действие (дистанция 60 фт). Восстанавливает хиты в размере 1d4 + мод. магии." },
    { name: "Сон", level: 1, classes: ["Бард", "Волшебник", "Чародей"], desc: "Погружает существ в магический сон. Воздействует на существ в 20-фт сфере суммарно на 5d8 текущих хитов, начиная с самых раненых." },
    { name: "Тензеров плавающий диск", level: 1, classes: ["Волшебник"], desc: "Ритуал. Создает круглую парящую платформу из силы, которая следует за вами и перевозит до 500 фунтов груза в течение 1 часа." },
    { name: "Ужасный смех Таши", level: 1, classes: ["Бард", "Волшебник"], desc: "Концентрация. Спас Мудрости. Цель падает ничком от дикого смеха, становится недееспособной и не может подняться." },
    { name: "Хроматический шар", level: 1, classes: ["Волшебник", "Чародей"], desc: "Дальняя атака заклинанием. Наносит 3d8 урона выбранного вами типа (кислота, холод, огонь, молния, гром или яд)." },
    { name: "Цветные брызги", level: 1, classes: ["Волшебник", "Чародей"], desc: "Конус 15 фт. Ослепляет существ яркими вспышками света. Воздействует суммарно на 6d10 хитов существ, начиная с наименьшего." },
    { name: "Щит веры", level: 1, classes: ["Жрец", "Паладин"], desc: "Бонусное действие. Концентрация. Окружает существо сияющим защитным полем, дающим +2 к КД." },
    { name: "Щит", level: 1, classes: ["Волшебник", "Чародей"], desc: "Реакция. Дает +5 к вашему КД против вызвавшей его атаки и защищает от Волшебной стрелы до начала вашего следующего хода." },
{ name: "Бесследное передвижение", level: 2, classes: ["Друид", "Следопыт"], desc: "Концентрация. Вся группа в радиусе 30 фт получает бонус +10 к проверкам Скрытности." },
    { name: "Клеймящая кара", level: 2, classes: ["Паладин"], desc: "Следующее попадание оружием наносит дополнительные 2d6 урона излучением и заставляет цель светиться." },
    { name: "Внушение", level: 2, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "Концентрация. Спас Мудрости. Вы внушаете цель выполнить разумное действие (до 8 часов)." },
    { name: "Видение невидимого", level: 2, classes: ["Волшебник", "Чародей", "Колдун"], desc: "Вы видите невидимых существ и предметы, а также заглядываете на Эфирный план на 1 час." },
    { name: "Глухота/Слепота", level: 2, classes: ["Бард", "Жрец", "Волшебник", "Чародей"], desc: "Спас Телосложения. Ослепляет или оглушает врага на 1 минуту. Спас повторить в конце каждого хода." },
    { name: "Дребезги", level: 2, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "Сфера 10 фт. Спас Телосложения. 3d8 урона звуком. Хрупкие и кристаллические предметы ломаются." },
    { name: "Духовное оружие", level: 2, classes: ["Жрец"], desc: "Бонусное. Создает призрачный клинок. Атака бонусным действием наносит 1d8 + мод. силового урона." },
    { name: "Звездный сияющий взор", level: 2, classes: ["Волшебник"], desc: "Концентрация. Ваши глаза светятся, позволяя видеть сквозь обычную и магическую тьму на 60 фт." },
    { name: "Зов лесных зверей", level: 2, classes: ["Друид", "Следопыт"], desc: "Вы призываете мелких лесных животных, которые могут шпионить, передавать сообщения или отвлекать врагов." },
    { name: "Корона безумия", level: 2, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "Концентрация. Спас Мудрости. Очаровывает гуманоида, заставляя его атаковать ближайших союзников." },
    { name: "Левитация", level: 2, classes: ["Волшебник", "Чародей", "Изобретатель"], desc: "Концентрация. Поднимает существо или предмет весом до 500 фунтов вертикально в воздух до 20 фт." },
    { name: "Локация объекта", level: 2, classes: ["Жрец", "Друид", "Паладин", "Следопыт", "Волшебник"], desc: "Концентрация. Вы узнаете точное направление к знакомому предмету, если он в пределах 1000 фт." },
    { name: "Магический замок", level: 2, classes: ["Волшебник", "Изобретатель"], desc: "Магически запирает дверь, сундук или ворота. СЛ взлома отмычками или выбивания увеличивается на +10." },
    { name: "Магическое оружие", level: 2, classes: ["Паладин", "Волшебник", "Изобретатель"], desc: "Концентрация. Бонусное. Немагическое оружие становится магическим и дает +1 к броскам атаки и урона." },
    { name: "Шаг сквозь заросли", level: 2, classes: ["Друид", "Следопыт"], desc: "Дает цели иммунитет к замедлению от сложной природной местности и колючек на 1 час." },
    { name: "Невидимость", level: 2, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "Концентрация. Цель полностью невидима на 1 час (спадает досрочно при атаке или касте)." },
    { name: "Обнаружение мыслей", level: 2, classes: ["Бард", "Волшебник", "Чародей"], desc: "Концентрация. Позволяет читать поверхностные мысли существ в радиусе 30 фт без их ведома." },
    { name: "Опаляющий луч", level: 2, classes: ["Волшебник", "Чародей"], desc: "Выпускает 3 луча. Нужен бросок атаки заклинанием для каждого. Каждый хит наносит 2d6 огнем." },
    { name: "Луч слабости", level: 2, classes: ["Волшебник", "Колдун"], desc: "Концентрация. Атака заклинанием. Наносит цели луч некротики: атаки оружием на основе Силы наносят лишь половину урона." },
    { name: "Отражения", level: 2, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "Создает 3 иллюзорные копии вокруг вас. Враги бьют по ним, сбрасывая иллюзии при попадании." },
    { name: "Паутина", level: 2, classes: ["Волшебник", "Чародей"], desc: "Концентрация. Заполняет куб 20 фт нитями. Спас Ловкости или существа становятся опутанными." },
    { name: "Паучий шаг", level: 2, classes: ["Волшебник", "Чародей", "Колдун", "Изобретатель"], desc: "Концентрация. Дает цели возможность ходить по стенам и потолкам, оставляя руки свободными." },
    { name: "Зона правды", level: 2, classes: ["Жрец", "Паладин"], desc: "Сфера 15 фт. Спас Мудрости. Существа внутри зоны физически не могут произнести преднамеренную ложь." },
    { name: "Успокоение эмоций", level: 2, classes: ["Бард", "Жрец"], desc: "Концентрация. Сфера 20 фт. Спас Харизмы. Подавляет эффекты испуга и очарования или гасит ярость врагов." },
    { name: "Помощь", level: 2, classes: ["Жрец", "Паладин"], desc: "Повышает максимум хитов и текущие хиты 3 союзников на +5 на 8 часов (без концентрации)." },
    { name: "Пылающая сфера", level: 2, classes: ["Друид", "Волшебник"], desc: "Концентрация. Создает шар огня 5 фт. Существа в пределах 5 фт от него получают 2d6 урона огнем." },
    { name: "Пылающий клинок", level: 2, classes: ["Друид"], desc: "Бонусное. Концентрация. Огненный меч в руке. Атака ближнего боя наносит 3d6 урона огнем." },
    { name: "Разговор с растениями", level: 2, classes: ["Бард", "Друид", "Следопыт"], desc: "Вы можете говорить с травой и деревьями, просить их освободить дорогу или рассказать о прошедших здесь." },
    { name: "Размытие", level: 2, classes: ["Волшебник", "Чародей", "Изобретатель"], desc: "Концентрация. Ваше тело дрожит и двоится. Все броски атак по вам совершаются с помехой." },
    { name: "Раскаленный металл", level: 2, classes: ["Бард", "Друид"], desc: "Концентрация. Металл цели раскаляется. Наносит 2d8 огнем, заставляет бросить оружие или бьет с помехой." },
    { name: "Темное зрение", level: 2, classes: ["Друид", "Следопыт", "Волшебник", "Чародей", "Изобретатель"], desc: "Касание. Дарует существу способность видеть в полной темноте на 60 фт на 8 часов." },
    { name: "Туманный шаг", level: 2, classes: ["Волшебник", "Чародей", "Колдун"], desc: "Бонусное действие. Мгновенная телепортация в свободную видимую точку в пределах 30 фт." },
    { name: "Тьма", level: 2, classes: ["Волшебник", "Чародей", "Колдун"], desc: "Концентрация. Сфера 15 фт непроницаемой черной тьмы, сквозь которую не видит даже Тёмное зрение." },
    { name: "Увеличение/Уменьшение", level: 2, classes: ["Волшебник", "Чародей", "Изобретатель"], desc: "Концентрация. Меняет размер существа. Увеличивает/уменьшает урон на 1d4 и дает преимущество/помеху на спасы Силы." },
    { name: "Удержание личности", level: 2, classes: ["Бард", "Жрец", "Волшебник", "Чародей", "Колдун"], desc: "Концентрация. Спас Мудрости. Полностью парализует одного гуманоида на время действия." },
    { name: "Улучшение характеристики", level: 2, classes: ["Бард", "Жрец", "Друид", "Волшебник", "Чародей"], desc: "Концентрация. Цель получает преимущество на все проверки одной выбранной характеристики на 1 час." }
    ,
{ name: "Снежный шквал Сниллока", level: 2, classes: ["Волшебник", "Чародей"], desc: "Дистанционная атака: сфера льда взрывается, нанося 3d6 урона холодом в радиусе 5 фт (спас Ловкости половина)." },
{ name: "Восставший труп (Анимация мертвецов)", level: 3, classes: ["Волшебник", "Жрец"], desc: "Превращает кости или труп гуманоида в послушного вам скелета или зомби на 24 часа." },
    { name: "Вспышка молнии", level: 3, classes: ["Волшебник", "Чародей"], desc: "Линия 100 фт. Спас Ловкости. Наносит 8d6 урона электричеством (половина при успехе)." },
    { name: "Газообразная форма", level: 3, classes: ["Волшебник", "Чародей", "Колдун"], desc: "Концентрация. Превращает согласное существо в туман. Цель получает скорость полета 10 фт и сопротивление физ. урону." },
    { name: "Восставшая кара", level: 3, classes: ["Паладин"], desc: "Бонусное. Концентрация. Следующий удар оружием наносит доп. 3d6 урона излучением, и цель сбивается с ног (спас Силы)." },
    { name: "Гнилостная волна", level: 3, classes: ["Паладин"], desc: "Сфера 30 фт. Спас Телосложения. Наносит 4d6 урона излучением или некротикой, цели падают ничком." },
    { name: "Дневной свет", level: 3, classes: ["Жрец", "Друид", "Паладин", "Следопыт", "Чародей"], desc: "Предмет испускает яркий солнечный свет в радиусе 60 фт. Рассеивает магическую тьму 3 круга и ниже." },
    { name: "Дружба с животными масс", level: 3, classes: ["Друид", "Следопыт"], desc: "Очаровывает до 3 зверей в пределах 30 фт на 24 часа (спас Мудрости)." },
    { name: "Духовные стражи", level: 3, classes: ["Жрец"], desc: "Концентрация. Вокруг вас кружат духи в радиусе 15 фт. Враги получают 3d8 урона излучением или некротикой и замедляются вдвое." },
    { name: "Защита от энергии", level: 3, classes: ["Жрец", "Друид", "Следопыт", "Волшебник", "Чародей", "Изобретатель"], desc: "Концентрация. Дарует цели сопротивление к одному типу урона (кислота, холод, огонь, молния или звук)." },
    { name: "Контрзаклинание", level: 3, classes: ["Волшебник", "Чародей", "Колдун"], desc: "Реакция. Прерывает сотворение заклинания другим существом, если его уровень 3 или ниже. Для высших кругов требуется проверка." },
    { name: "Магический круг", level: 3, classes: ["Волшебник", "Жрец", "Паладин", "Колдун"], desc: "Создает цилиндрический барьер радиусом 10 фт, который удерживает или не впускает исчадий, фей, нежить или элементалей." },
    { name: "Массовое исцеление словом", level: 3, classes: ["Жрец"], desc: "Бонусное действие (60 фт). Возвращает 1d4 + мод. магии хитов максимум 6 существам." },
    { name: "Маяк надежды", level: 3, classes: ["Жрец"], desc: "Концентрация. Союзники в зоне получают преим. на спасы Мудрости и от смерти, а лечение по ним всегда максимально." },
    { name: "Медленность", level: 3, classes: ["Волшебник", "Чародей"], desc: "Концентрация. До 6 существ в кубе 40 фт. Спас Мудрости. Скорость режется наполовину, КД и спасы Ловкости падают на -2, запрещены мультиатаки." },
    { name: "Мертвецы говорят (Разговор с мертвецом)", level: 3, classes: ["Бард", "Жрец"], desc: "Вы можете задать до 5 вопросов трупу, который всё еще обладает губами и языком." },
    { name: "Молния масс (Призыв молнии)", level: 3, classes: ["Друид"], desc: "Концентрация. Наносит 3d10 урона электричеством в точке на земле. Каждый ход действием можно вызывать новую молнию." },
    { name: "Надежная охрана (Нондетекшн)", level: 3, classes: ["Следопыт", "Волшебник"], desc: "Касание. Цель нельзя выследить или обнаружить с помощью магии прорицания и магических сенсоров в течение 8 часов." },
    { name: "Огненный шар", level: 3, classes: ["Волшебник", "Чародей"], desc: "Сфера радиусом 20 фт. Спасбросок Ловкости. Наносит 8d6 огненного урона (половина при успехе)." },
    { name: "Ослепительный свет (Узор гипноза)", level: 3, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "Концентрация. Куб 30 фт. Спас Мудрости. Сверкающий узор полностью завораживает и недееспособит цели." },
    { name: "Острые шипы", level: 3, classes: ["Друид", "Следопыт"], desc: "Концентрация. Земля в радиусе 20 фт покрывается шипами. Каждый 5 фт перемещения наносят существу 2d4 колющего урона." },
    { name: "Полёт", level: 3, classes: ["Волшебник", "Чародей", "Колдун", "Изобретатель"], desc: "Концентрация. Дарует существу скорость полета 60 фт на 10 минут." },
    { name: "Призрачный скакун", level: 3, classes: ["Волшебник"], desc: "Ритуал. Призывает призрачное квази-реальное животное со скоростью 100 фт на 1 час." },
    { name: "Призыв животных", level: 3, classes: ["Друид", "Следопыт"], desc: "Концентрация. 1 час. Призывает стаю верных духов природы в облике зверей (до 8 существ низкого CR)." },
    { name: "Рассеивание магии", level: 3, classes: ["Бард", "Жрец", "Друид", "Паладин", "Волшебник", "Чародей", "Колдун", "Изобретатель"], desc: "Любое заклинание 3 уровня или ниже на выбранном существе, предмете или зоне мгновенно прекращается." },
    { name: "Слияние с камнем", level: 3, classes: ["Жрец", "Друид", "Следопыт"], desc: "Вы физически сливаетесь с каменной стеной или валуном, оставаясь там до 8 часов. Вы не видите, что снаружи, но слышите." },
    { name: "Смертельное облако (Вонючий туман)", level: 3, classes: ["Волшебник", "Чародей"], desc: "Концентрация. Сфера 20 фт отвратительного тумана. Спас Телосложения или существо теряет действие в свой ход." },
    { name: "Снятие проклятия", level: 3, classes: ["Бард", "Жрец", "Паладин", "Волшебник"], desc: "Касание. Снимает все проклятия с существа или предмета. Если предмет проклят, владелец может его выбросить." },
    { name: "Страх", level: 3, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "Концентрация. Конус 30 фт. Спас Мудрости или существа бросают всё и бегут от вас в панике." },
    { name: "Ускорение", level: 3, classes: ["Волшебник", "Чародей", "Изобретатель"], desc: "Концентрация. Скорость цели удваивается, КД увеличивается на +2, и она получает дополнительное действие каждый ход." },
    { name: "Хождение по воде", level: 3, classes: ["Жрец", "Друид", "Следопыт", "Изобретатель"], desc: "До 10 существ получают способность ходить по воде, грязи, лаве или кислоте, не погружаясь и не получая урона от поверхности (на 1 час)." },
    { name: "Ясновидение", level: 3, classes: ["Бард", "Жрец", "Волшебник"], desc: "Концентрация. Создает невидимый магический сенсор в знакомом месте, позволяющий вам слышать или видеть происходящее там." },
{ name: "Виноградная лоза (Удерживание земли)", level: 4, classes: ["Друид", "Следопыт"], desc: "Концентрация. Побеги хватают существ в радиусе 30 фт. Спас Силы или цель подтягивается к центру и опутывается." },
    { name: "Высшая невидимость", level: 4, classes: ["Бард", "Волшебник", "Чародей"], desc: "Концентрация. Делает цель полностью невидимой на 1 минуту. Не спадает, даже если цель атакует, получает урон или колдует." },
    { name: "Галлюцинаторный ландшафт", level: 4, classes: ["Бард", "Друид", "Волшебник"], desc: "Вы заставляете одну местность выглядеть, звучать и пахнуть как совершенно другая (например, болото превращается в луг). Длится 24 часа." },
    { name: "Дверь измерений", level: 4, classes: ["Бард", "Волшебник", "Колдун"], desc: "Вы и один согласный спутник вашего размера мгновенно телепортируетесь в любую точку в пределах 500 фт, даже если вы её не видите." },
    { name: "Доблестная кара", level: 4, classes: ["Паладин", "Изобретатель"], desc: "Бонусное. Концентрация. Следующий удар оружием наносит доп. 4d6 урона излучением, а вы и ваши союзники в пределах 30 фт восстанавливаете 1d6 + мод. хитов." },
    { name: "Защитная аура (Аура жизни)", level: 4, classes: ["Паладин"], desc: "Концентрация. Аура 30 фт. Защищает союзников от снижения максимума хитов, дает сопротивление некротическому урону, а при 0 ПЗ существа возвращают 1 хит каждый ход." },
    { name: "Аура чистоты", level: 4, classes: ["Паладин"], desc: "Концентрация. Аура 30 фт. Дает союзникам иммунитет к болезням, сопротивление урону ядом и преимущество на спасброски от большинства состояний (ослепление, очарование, испуг и т.д.)." },
    { name: "Изгнание", level: 4, classes: ["Жрец", "Паладин", "Волшебник", "Чародей", "Колдун"], desc: "Концентрация. Спас Мудрости. Отправляет существо на его родной план существования (чужеродные твари изгоняются навсегда, местные — запираются в карманном плане)." },
    { name: "Каменная кожа", level: 4, classes: ["Друид", "Следопыт", "Волшебник", "Чародей", "Изобретатель"], desc: "Концентрация. Расходный компонент. Дарует цели сопротивление к немагическому дробящему, колющему и рубящему урону на 1 час." },
    { name: "Каменный облик (Формование камня)", level: 4, classes: ["Жрец", "Друид", "Волшебник"], desc: "Вы мгновенно изменяете форму каменного объекта среднего размера, превращая его в оружие, дверь, проход или герметичный ящик." },
    { name: "Контроль воды", level: 4, classes: ["Жрец", "Друид", "Волшебник"], desc: "Концентрация. Позволяет управлять большими массами воды: вызывать наводнение, разделять воду на две стены, создавать водовороты или усмирять волны." },
    { name: "Ледяной шторм", level: 4, classes: ["Друид", "Волшебник", "Чародей"], desc: "Цилиндр радиусом 20 фт. Наносит 2d8 дробящего и 4d6 урона холодом, превращая землю под собой в труднопроходимую местность." },
    { name: "Локация существа", level: 4, classes: ["Жрец", "Друид", "Паладин", "Следопыт", "Волшебник"], desc: "Концентрация. Вы узнаете точное направление и перемещение конкретного существа, если оно находится в пределах 2000 фунтов от вас." },
    { name: "Огненный щит", level: 4, classes: ["Волшебник", "Изобретатель"], desc: "Вы окружаете себя пламенем (теплым или холодным). Дает сопротивление к холоду или огню, а бьющие вас в пределах 5 фт получают в ответ 2d8 урона." },
    { name: "Ориентир (Свобода перемещения)", level: 4, classes: ["Бард", "Жрец", "Друид", "Паладин", "Следопыт", "Изобретатель"], desc: "Дает существу иммунитет к параличу, опутанию, заклинаниям замедления и сложной местности на 1 час. Позволяет автоматически вырываться из захватов за 5 фт движения." },
    { name: "Полиморф (Превращение)", level: 4, classes: ["Бард", "Друид", "Волшебник", "Чародей"], desc: "Концентрация. Спас Мудрости. Превращает любое существо в зверя, чей показатель опасности (CR) или уровень не превышает уровень/хиты цели." },
    { name: "Подчинение животного", level: 4, classes: ["Друид", "Следопыт"], desc: "Концентрация. Спас Мудрости. Вы берете под полный телепатический контроль любого зверя на 1 минуту." },
    { name: "Стена огня", level: 4, classes: ["Друид", "Волшебник", "Чародей", "Колдун", "Изобретатель"], desc: "Концентрация. Создает стену пламени длиной до 60 фт. Существа внутри или при приближении к её лицевой стороне получают 5d8 огненного урона." },
    { name: "Страж веры", level: 4, classes: ["Жрец"], desc: "Призывает неподвижного призрачного стража. Когда враг подходит, страж бьет его, наносит 20 урона излучением (исчезает после нанесения 60 урона суммарно)." },
    { name: "Увядание", level: 4, classes: ["Волшебник", "Чародей", "Колдун", "Изобретатель"], desc: "Спас Телосложения (растения и элементали кидают с помехой и получают макс. урон). Наносит 8d8 некротического урона одиночной цели." },
    { name: "Фабрикация", level: 4, classes: ["Волшебник"], desc: "Превращает сырье (дерево, руду, шкуры) в готовый сложный предмет (мост, латы, одежду) за 10 минут, если у вас есть навыки владения инструментами." },
{ name: "Богохульство (Священное слово)", level: 5, classes: ["Жрец"], desc: "Произносит священное слово. Все выбранные существа в пределах 30 фт проходят спас Мудрости. Ослабляет, ослепляет или мгновенно убивает нежить/извергов с низким HP." },
    { name: "Высшее восстановление", level: 5, classes: ["Жрец", "Друид", "Бард", "Изобретатель"], desc: "Снимает с цели одно мощное истощение, окаменение, проклятие, эффект безумия или восстанавливает сниженный максимум хитов." },
    { name: "Длань Бигби", level: 5, classes: ["Волшебник"], desc: "Концентрация. Создает парящую руку из силы. Может бить на 4d6 урона, толкать, хватать великанов или служить вам укрытием." },
    { name: "Исцеление ран масс", level: 5, classes: ["Бард", "Жрец", "Друид"], desc: "Направляет волну энергии. Восстанавливает 3d8 + мод. магии хитов максимум 6 существам в 30-футовой сфере." },
    { name: "Конус холода", level: 5, classes: ["Волшебник", "Чародей"], desc: "Конус 60 фт. Спас Телосложения. Наносит 8d8 урона холодом. Убитые этим заклинанием существа превращаются в ледяные статуи." },
    { name: "Массовое внушение", level: 5, classes: ["Бард", "Жрец", "Волшебник", "Чародей", "Колдун"], desc: "Спас Мудрости. Вы внушаете выполнить разумное действие группе до 12 существ одновременно (длится до 24 часов)." },
    { name: "Оживить объект", level: 5, classes: ["Бард", "Волшебник", "Чародей"], desc: "Концентрация. Оживляет до 10 немагических предметов (стулья, монеты, мечи), превращая их в преданных вам существ с КД и атаками." },
    { name: "Оживление (Реинкарнация)", level: 5, classes: ["Друид"], desc: "Расходный компонент. Возвращает к жизни душу, умершую не более 10 дней назад, но формирует для нее абсолютно случайное новое тело новой расы." },
    { name: "Подчинение чудовища", level: 5, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "Концентрация. Спас Мудрости (с преимуществом, если в бою). Вы берете под полный телепатический контроль любое существо (дракона, гиганта, аберрацию)." },
    { name: "Призыв элементаля", level: 5, classes: ["Друид", "Волшебник"], desc: "Концентрация. 1 час. Призывает элементаля земли, воздуха, огня или воды (CR 5). Если ваша концентрация сбита, он становится враждебным группе." },
    { name: "Святилище (Рассвет)", level: 5, classes: ["Жрец", "Паладин"], desc: "Вы создаете сияющую зону 10х10 фт. Существа внутри защищены от злых сил, а нечисть получает урон излучением при входе." },
    { name: "Стена силы", level: 5, classes: ["Волшебник"], desc: "Создает невидимый, неразрушимый барьер из чистой силы (стену или сферу). Ничто не может физически или магически пройти сквозь него." },
    { name: "Стена камня", level: 5, classes: ["Друид", "Волшебник", "Чародей"], desc: "Концентрация. Создает прочную каменную стену из соединенных панелей. Если удерживать концентрацию все 10 минут, стена становится постоянной." },
    { name: "Телекинез", level: 5, classes: ["Волшебник", "Чародей"], desc: "Концентрация. Вы можете каждый ход перемещать силой мысли существ или предметы весом до 1000 фунтов, проходя проверки интеллекта против их силы." },
{ name: "Вред", level: 6, classes: ["Жрец"], desc: "Спас Телосложения. Наносит 14d6 некротического урона и снижает максимум хитов цели на эту же величину. Хитпоинты не могут упасть ниже 1." },
    { name: "Долина смерти (Круг смерти)", level: 6, classes: ["Волшебник", "Чародей", "Колдун"], desc: "Сфера радиусом 60 фт. Спас Телосложения. Наносит 8d6 некротического урона всем существам в зоне поражения." },
    { name: "Истинное зрение", level: 6, classes: ["Жрец", "Волшебник", "Чародей", "Колдун", "Изобретатель"], desc: "Дарует существу способность видеть истинную суть вещей на 120 фт: сквозь иллюзии, скрытые двери, невидимость и в магической тьме." },
    { name: "Исцеление", level: 6, classes: ["Жрец", "Друид"], desc: "Восстанавливает ровно 70 хитов одному существу. Снимает слепоту, глухоту и все болезни." },
    { name: "Каменный доспех (Плоть в камень)", level: 6, classes: ["Волшебник", "Колдун"], desc: "Концентрация. Спасбросок Телосложения. Постепенно превращает существо в каменную статую в течение нескольких раундов." },
    { name: "Магическое путешествие (Тропа ветра)", level: 6, classes: ["Друид"], desc: "Концентрация. Вы и союзники можете перемещаться по воздуху в форме легкого ветерка со скоростью полета 30 фт." },
    { name: "Массовое внушение", level: 6, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "Спас Мудрости. Вы внушаете одну и ту же разумную команду группе до 12 существ на срок до 24 часов." },
    { name: "Пир героев", level: 6, classes: ["Жрец", "Друид"], desc: "Расходный компонент. Создает пир для 12 существ. Дает иммунитет к яду, испугу, преимущество на спасы Мудрости и +2d10 к максимуму ПЗ на 24 часа." },
    { name: "Пленение души", level: 6, classes: ["Волшебник", "Колдун"], desc: "Реакция при смерти существа. Заключает его душу в клетку, лишая возможности воскрешения и позволяя вам допрашивать её." },
    { name: "Солнечный луч", level: 6, classes: ["Друид", "Волшебник", "Чародей"], desc: "Концентрация. Линия 60 фт. Наносит 4d8 урона излучением и ослепляет цели на 1 ход (спас Телосложения половина). Можно повторять каждый ход." },
    { name: "Стена льда", level: 6, classes: ["Волшебник"], desc: "Концентрация. Создает ледяную стену из 10 панелей. Наносит 10d6 урона холодом при появлении и 5d6 тем, кто пытается пройти сквозь неё." },
    { name: "Тайный взгляд", level: 6, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "Концентрация. Ваши глаза сияют. Позволяет видеть сквозь невидимость, иллюзии, а также смотреть в Эфирный план." },
    { name: "Цепная молния", level: 6, classes: ["Волшебник", "Чародей"], desc: "Наносит 10d8 урона молнией выбранной цели. От неё отделяются еще 3 молнии, бьющие в другие цели в пределах 30 фт." },
{ name: "Божественное слово", level: 7, classes: ["Жрец"], desc: "Произносит священное слово. Все выбранные враги в пределах 30 фт проходят спасбросок Мудрости. В зависимости от их текущего HP они оглушаются, ослепляются или мгновенно умирают (изверги/нежить изгоняются)." },
    { name: "Великолепный особняк Морденкайнена", level: 7, classes: ["Бард", "Волшебник"], desc: "Создает скрытый вход в межпланарный роскошный особняк на 24 часа. Внутри находится пиршество, слуги-призраки и абсолютная защита от внешнего мира." },
    { name: "Длань смерти (Палец смерти)", level: 7, classes: ["Волшебник", "Чародей", "Колдун"], desc: "Спас Телосложения. Наносит 7d8 + 30 некротического урона одиночной цели. Если цель умирает от этого заклинания, она мгновенно восстает как зомби под вашим вечным контролем." },
    { name: "Изоляция (Секвестр)", level: 7, classes: ["Волшебник"], desc: "Расходный компонент. Погружает существо или предмет в состояние анабиоза на неопределенный срок. Цель становится невидимой, неосязаемой для магии прорицания и перестает стареть." },
    { name: "Огненная буря", level: 7, classes: ["Жрец", "Друид", "Чародей"], desc: "Вызывается огненный шторм, состоящий из десяти соединенных кубов 10х10 фт. Спасбросок Ловкости. Наносит 7d10 урона огнем и выжигает растительность." },
    { name: "Отражающее заклинание (Реверсия)", level: 7, classes: ["Волшебник", "Чародей"], desc: "Реакция. Вы создаете барьер, который перенаправляет обратно в кастера любое заклинание 7 круга или ниже, направленное лично в вас." },
    { name: "Перемещение по планам (Планарный переход)", level: 7, classes: ["Жрец", "Друид", "Волшебник", "Чародей", "Колдун"], desc: "Расходный компонент. Касание. Перемещает вас и до 8 согласных существ на другой план существования (или изгоняет врага при провале спаса Харизмы)." },
    { name: "Проекция астрала", level: 7, classes: ["Волшебник", "Колдун"], desc: "Концентрация. Вы и до 8 существ проецируете свои астральные тела в Астральный план, оставляя физические оболочки в безопасности и анабиозе." },
    { name: "Радужные брызги", level: 7, classes: ["Волшебник", "Чародей"], desc: "Конус 60 фт. Выпускает 8 лучей света. Спасбросок Ловкости. В зависимости от цвета луча наносит 10d6 урона определенного типа (огонь, кислота, молния и т.д.) или накладывает особый эффект." },
    { name: "Регенерация", level: 7, classes: ["Жрец", "Друид"], desc: "Касание. Стимулирует естественное восстановление. Цель мгновенно восстанавливает 4d8 + 15 хитов, а затем возвращает по 1 хиту в начале каждого своего хода в течение 1 часа. Отращивает отрубленные конечности." },
    { name: "Смена формы (Превращение масс)", level: 7, classes: ["Друид"], desc: "Концентрация. На 1 час вы принимаете облик любого существа (включая драконов или гигантов) с показателем опасности (CR), равным вашему уровню или ниже, сохраняя свой интеллект и личность." },
    { name: "Телепортация", level: 7, classes: ["Бард", "Волшебник", "Чародей"], desc: "Мгновенно переносит вас и до 8 согласных существ в любое знакомое место на этом же плане. Шанс ошибки и смещения точки прибытия зависит от того, насколько хорошо вы знаете локацию." },
{ name: "Антимагическое поле", level: 8, classes: ["Жрец", "Волшебник"], desc: "Концентрация. Вокруг вас создается невидимая сфера радиусом 10 фт. Внутри неё полностью подавляется любая магия: заклинания не работают, а магические предметы становятся обычными." },
    { name: "Взрыв разума (Слабоумие)", level: 8, classes: ["Друид", "Волшебник", "Чародей", "Колдун"], desc: "Спасбросок Интеллекта. Наносит цели 4d6 психического урона и превращает её разум в ничто. Значения Интеллекта и Харизмы цели падают до 1, она теряет способность колдовать и говорить (спас рероллится раз в 30 дней)." },
    { name: "Власть над погодой (Управление погодой)", level: 8, classes: ["Жрец", "Друид", "Волшебник"], desc: "Концентрация. Вы получаете полный контроль над климатом в радиусе нескольких миль на 8 часов. Позволяет плавно изменять температуру, силу ветра и осадки (от ясного неба до жуткого урагана)." },
    { name: "Землетрясение", level: 8, classes: ["Жрец", "Друид", "Волшебник", "Чародей"], desc: "Концентрация. Вы вызываете жуткие подземные толчки в радиусе 100 фт. Земля трескается, постройки рушатся, нанося колоссальный урон, а все существа в зоне каждую секунду падают ничком (спас Ловкости)." },
    { name: "Лабиринт", level: 8, classes: ["Волшебник"], desc: "Концентрация. Вы мгновенно изгоняете цель в карманное планарное измерение, представляющее собой бесконечный лабиринт. Существо заперто там без спасброска и может выбраться, только если потратит действие на сложную проверку Интеллекта." },
    { name: "Массовое исцеление", level: 8, classes: ["Жрец"], desc: "Вы вливаете чистую божественную энергию в поле боя. Вы распределяете ровно 700 хитов лечения в любых пропорциях между любым количеством существ в пределах 60 фт." },
    { name: "Подчинение гуманоида масс", level: 8, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "Концентрация. Спас Мудрости. Вы берете под полный телепатический контроль группу гуманоидов одновременно на срок до 8 часов." },
    { name: "Полуплан", level: 8, classes: ["Волшебник", "Колдун"], desc: "Вы создаете скрытую дверь на плоской поверхности, которая ведет в ваше собственное уникальное карманное измерение — пустую каменную комнату 30х30 фт, где можно прятать вещи или врагов." },
    { name: "Священная аура", level: 8, classes: ["Жрец"], desc: "Концентрация. На 1 минуту вас окружает божественный свет в радиусе 30 фт. Все союзники в ауре получают преимущество на ВСЕ спасброски, а враги бьют по ним с помехой. Если нежить или изверг бьет союзника, они ослепляются." },
    { name: "Солнечная вспышка", level: 8, classes: ["Друид", "Волшебник", "Чародей"], desc: "Взрыв ослепительного света в радиусе 40 фт. Наносит 12d6 урона излучением и навсегда ослепляет цели (спас Телосложения половина урона и слепота на 1 ход). Нежить и слизни кидают с помехой." },
    { name: "Язык солнца и луны масс (Послание масс)", level: 8, classes: ["Бард"], desc: "Вы можете отправить телепатическое мысленное послание до 25 слов любому количеству существ по всему миру одновременно, и они поймут его, даже если не знают языков." },
{ name: "Исполнение желаний (Исполнение Желания)", level: 9, classes: ["Волшебник", "Чародей"], desc: "Сильнейшее заклинание в игре. Позволяет мгновенно продублировать абсолютно любое другое заклинание 8 круга или ниже без траты компонентов и времени. Либо сотворить любое чудо по согласованию с Мастером (риск потерять заклинание навсегда — 33%)." },
    { name: "Истинное воскрешение", level: 9, classes: ["Жрец", "Друид"], desc: "Расходный компонент. Возвращает к жизни существо, умершее не более 200 лет назад. Ему восстанавливаются все хиты, снимаются все проклятия и болезни, а если физическое тело было полностью уничтожено — заклинание формирует новое." },
    { name: "Истинное превращение (Истинный Полиморф)", level: 9, classes: ["Бард", "Волшебник", "Колдун"], desc: "Концентрация. Превращает существо в другого персонажа, монстра (включая древних драконов) или неодушевленный предмет. Если удерживать концентрацию полные 1 час, превращение становится постоянным." },
    { name: "Метеоритный дождь", level: 9, classes: ["Волшебник", "Чародей"], desc: "Вы обрушиваете 4 огромных огненных метеора в разные точки поля боя. Каждый взрывается в радиусе 40 фт, нанося суммарно 20d6 огненного и 20d6 дробящего урона (всего 40d6 урона, спас Ловкости наполовину)." },
    { name: "Пленение", level: 9, classes: ["Волшебник", "Колдун", "Изобретатель"], desc: "Расходный компонент. Спас Мудрости. Навсегда замуровывает существо в магическую тюрьму: глубоко под землей, внутри крошечного драгоценного камня или погружает в бесконечный сон. Цель перестает стареть и не нуждается в еде." },
    { name: "Врата", level: 9, classes: ["Жрец", "Волшебник", "Чародей", "Колдун"], desc: "Концентрация. Открывает межпространственный портал в конкретную точку на другом плане существования на 1 минуту. Если вы произнесете имя конкретного существа, портал принудительно затянет его к вам, где бы оно ни находилось." },
    { name: "Слово силы: Убийство", level: 9, classes: ["Волшебник", "Чародей", "Колдун"], desc: "Вы произносите одно тайное слово. Если у цели в пределах 60 фт сейчас 100 хитов или меньше, она мгновенно умирает без каких-либо спасбросков и проверок. На существ со 101+ хитами не действует." },
    { name: "Слово силы: Исцеление", level: 9, classes: ["Бард", "Жрец"], desc: "Вы произносите слово созидания. Одно существо, которого вы коснулись, мгновенно восстанавливает все свои хиты до максимума. Заклинание также снимает состояния очарования, испуга, паралича, ослепления и оглушения." },
    { name: "Психический крик", level: 9, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "Вы заставляете взорваться разум до 10 существ в пределах 90 фт. Спасбросок Интеллекта. Наносит 14d6 психического урона и оглушает цели. Если существо погибает от этого урона, его голова взрывается." },
    { name: "Проекция астрала масс", level: 9, classes: ["Жрец", "Волшебник", "Колдун"], desc: "Концентрация. Вы и до 8 существ проецируете свои астральные тела в Астральный план, оставляя физические оболочки в безопасности и анабиозе." },
    { name: "Радужная стена (Сфера)", level: 9, classes: ["Волшебник"], desc: "Создает сияющую сферу радиусом 15 фт вокруг вас. Она состоит из 7 слоев разного цвета. Каждый слой уничтожает снаряды, магию, наносит по 10d6 урона своего типа при попытке пройти сквозь нее и накладывает слепоту/окаменение." },
    { name: "Предвидение", level: 9, classes: ["Бард", "Друид", "Волшебник"], desc: "Вы касаетесь существа и даруете ему способность на 8 часов видеть ближайшее будущее. Цель не может быть застигнута врасплох, получает преимущество на ВСЕ броски атак, проверок и спасбросков, а враги бьют по ней с помехой." },

    { name: "Пляшущие огоньки", level: 0, classes: ["Бард", "Волшебник", "Чародей", "Изобретатель"], desc: "Конц. До 4 огоньков в 120 фт, светят ярким светом в 10 фт." },
    { name: "Сообщение", level: 0, classes: ["Бард", "Волшебник", "Чародей", "Изобретатель"], desc: "Шепчете сообщение цели в 120 фт. Цель может ответить шепотом." },
    { name: "Туманное облако", level: 1, classes: ["Друид", "Следопыт", "Чародей", "Волшебник"], desc: "Конц. Сфера тумана радиусом 20 фт. Сильно застилает область." },
    { name: "Подводное дыхание", level: 3, classes: ["Друид", "Следопыт", "Волшебник", "Изобретатель"], desc: "Рит. До 10 существ получают способность дышать под водой на 24 часа." },

    { name: "Кислотный всплеск", level: 0, classes: ["Волшебник", "Чародей", "Изобретатель"], desc: "Спасбросок Ловкости 1 или 2 целей в 5 фт. 1d6 урона кислотой." },
    { name: "Защита от оружия", level: 0, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "1 раунд. Сопротивление дробящему, колющему и рубящему урону от атак оружием." },
    { name: "Друзья", level: 0, classes: ["Бард", "Волшебник", "Чародей", "Колдун"], desc: "Конц. До 1 мин. Преимущество на проверки Харизмы против существа. По окончании цель понимает, что ее очаровали." },
    { name: "Уход за умирающим", level: 0, classes: ["Жрец", "Изобретатель"], desc: "Касание. Существо с 0 хитов становится стабилизированным." },
    { name: "Терновый кнут", level: 0, classes: ["Друид", "Изобретатель"], desc: "Атака в ближнем бою (30 фт). 1d6 колющего урона, и цель притягивается к вам на 10 фт." },
    { name: "Жир", level: 1, classes: ["Волшебник", "Чародей", "Изобретатель"], desc: "Квадрат 10 фт на 1 мин. Спасбросок Ловкости при входе или падение ничком. Труднопроходимая местность." },
    { name: "Призыв фамильяра", level: 1, classes: ["Волшебник"], desc: "Рит. 1 час. Призывает духа-фамильяра в форме зверька. Телепатическая связь и колдовство заклинаний с касанием через него." },
    { name: "Невидимый слуга", level: 1, classes: ["Бард", "Волшебник", "Колдун"], desc: "Рит. 1 час. Создает невидимую бесформенную силу для выполнения простых поручений в пределах 60 фт." },
    { name: "Доспехи Агафиса", level: 1, classes: ["Колдун"], desc: "1 час. Вы получаете 5 временных хитов. Пока они есть, атакующие вас в ближнем бою получают 5 урона холодом." },
    { name: "Адское возмездие", level: 1, classes: ["Колдун"], desc: "Реакция при получении урона. Спасбросок Ловкости. Обидчик получает 2d10 урона огнем (половина при успехе)." },
    { name: "Пылающий шар", level: 2, classes: ["Друид", "Волшебник"], desc: "Бонусное. Конц. 1 мин. Сфера огня диаметром 5 фт. Спас Ловк. 2d6 урона огнем. Перемещается на 30 фт." },
    { name: "Кислотная стрела Мельфа", level: 2, classes: ["Волшебник", "Чародей"], desc: "Дальняя атака (90 фт). 4d4 урона кислотой сразу и 2d4 в конце след. хода цели. При промахе - 2d4 сразу." },
    { name: "Волшебный замок", level: 2, classes: ["Волшебник", "Изобретатель"], desc: "Касание. До рассеивания. Запирает дверь, окно или сундук (+10 к СЛ взлома). Вы можете задать пароль." },
    { name: "Порыв ветра", level: 2, classes: ["Друид", "Волшебник", "Чародей"], desc: "Конц. 1 мин. Линия 60 фт ветра. Спас Силы или отталкивание на 15 фт. Движение сквозь нее затруднено." },
    { name: "Ложная аура Нистула", level: 2, classes: ["Волшебник"], desc: "24 часа. Касание. Изменяет способ восприятия магии или типа существа/предмета заклинаниями предсказания." },
    { name: "Полет", level: 3, classes: ["Чародей", "Колдун", "Волшебник", "Изобретатель"], desc: "Конц. 10 мин. Касание. Существо получает скорость полета 60 фт." },
    { name: "Молния", level: 3, classes: ["Чародей", "Волшебник"], desc: "Линия 100 фт длиной и 5 фт шириной. Спасбросок Ловкости. 8d6 урона электричеством (половина при успехе)." },
    { name: "Касание вампира", level: 3, classes: ["Колдун", "Волшебник"], desc: "Конц. 1 мин. Атака касанием наносит 3d6 некротического урона. Вы лечитесь на половину нанесенного урона." },
    { name: "Огненная стена", level: 4, classes: ["Друид", "Чародей", "Волшебник"], desc: "Конц. 1 мин. Стена огня до 60 фт. Спасбросок Ловкости. 5d8 урона огнем при появлении и 5d8 рядом с ней." },
    { name: "Облако смерти", level: 5, classes: ["Чародей", "Волшебник"], desc: "Конц. 10 мин. Сфера ядовитого тумана радиусом 20 фт. Спас Телосложения. 5d8 урона ядом. Движется от вас на 10 фт/раунд." },
    { name: "Оживление", level: 5, classes: ["Бард", "Жрец", "Паладин"], desc: "1 час. Касание. Возвращает к жизни существо, умершее не более 10 дней назад, с 1 хитом. Штраф -4 к броскам на 4 дня." },

    { name: "Тревога (Сигнализация)", level: 1, classes: ["Следопыт", "Волшебник", "Изобретатель"], desc: "Рит. 8 часов. Куб 20 фт. Оповещает мысленно или звоном, если область пересекает существо без пароля." },
    { name: "Руки Хадара", level: 1, classes: ["Колдун"], desc: "Спасбросок Ловкости всех в 10 фт. 2d6 урона некротической энергией и цель лишается реакций до своего след. хода." },
    { name: "Вынужденная дуэль", level: 1, classes: ["Паладин"], desc: "Бонусное. Конц. 1 мин. Спас Мудрости. Цель получает помеху на атаки по другим и не может отойти дальше 30 фт." },
    { name: "Создание или уничтожение воды", level: 1, classes: ["Жрец", "Друид"], desc: "Создает или уничтожает до 10 галлонов чистой воды в открытой емкости (или туман в кубе 30 фт)." },
    { name: "Божественное благоволение", level: 1, classes: ["Паладин"], desc: "Бонусное. Конц. 1 мин. Ваши атаки оружием наносят дополнительно 1d4 урона излучением при попадании." },
    { name: "Град шипов", level: 1, classes: ["Следопыт"], desc: "Бонусное. Конц. 1 мин. След. дальняя атака оружием взрывается шипами (спас Ловк., 1d10 колющего урона в 5 фт)." },
    { name: "Нанесение ран", level: 1, classes: ["Жрец"], desc: "Атака заклинанием ближнего боя. Наносит 3d10 некротического урона при попадании." },
    { name: "Громовая кара", level: 1, classes: ["Паладин"], desc: "Бонусное. Конц. 1 мин. След. атака оружием наносит +2d6 звука, спас Силы или цель отлетает на 10 фт и падает ничком." },
    { name: "Гневная кара", level: 1, classes: ["Паладин"], desc: "Бонусное. Конц. 1 мин. След. атака оружием наносит +1d6 психического урона, спас Мудрости или цель испугана." },
    { name: "Опутывающий удар", level: 1, classes: ["Следопыт"], desc: "Бонусное. Конц. 1 мин. След. атака оружием опутывает цель шипастыми лозами (спас Силы, 1d6 колющего урона каждый ход)." },
    { name: "Дружба с животными", level: 1, classes: ["Бард", "Друид", "Следопыт"], desc: "24 часа. Спасбросок Мудрости. Зверь с Интеллектом менее 4 становится очарованным вами." },
    { name: "Облако кинжалов", level: 2, classes: ["Бард", "Чародей", "Колдун", "Волшебник"], desc: "Конц. 1 мин. Куб 5 фт. Существо получает 4d4 рубящего урона при входе или начале хода в области." },
    { name: "Вечный огонь", level: 2, classes: ["Жрец", "Волшебник", "Изобретатель"], desc: "Касание. До рассеивания. Создает пламя на предмете, светящее как факел (яркий 20 фт, тусклый 20 фт) без тепла." },
    { name: "Завеса стрел", level: 2, classes: ["Следопыт"], desc: "8 часов. До 4 стрел в земле (30 фт). Автоматически стреляют во врагов в 30 фт (спас Ловкости, 1d6 колющего урона)." },
    { name: "Поиск ловушек", level: 2, classes: ["Жрец", "Друид", "Следопыт"], desc: "Вы чувствуете присутствие любых ловушек в пределах линии обзора (120 фт) и узнаете характер опасности." },
    { name: "Нетленные останки", level: 2, classes: ["Жрец", "Волшебник"], desc: "Рит. Касание. 10 дней. Защищает труп от разложения и продлевает лимит времени для воскрешения." },
    { name: "Стук", level: 2, classes: ["Бард", "Чародей", "Волшебник"], desc: "Дистанция 60 фт. Мгновенно отпирает один замок (включая Волшебный замок). Издает громкий стук на 300 фт." },
    { name: "Поиск животных или растений", level: 2, classes: ["Бард", "Друид", "Следопыт"], desc: "Рит. Описываете вид зверя или растения. Узнаете направление и расстояние до ближайшей особи в 5 милях." },
    { name: "Волшебные уста", level: 2, classes: ["Бард", "Волшебник", "Изобретатель"], desc: "Рит. Касание. До рассеивания. Предмет обретает рот, произносящий до 25 слов при срабатывании триггера." },
    { name: "Защита от яда", level: 2, classes: ["Жрец", "Друид", "Паладин", "Следопыт", "Изобретатель"], desc: "Касание. 1 час. Нейтрализует яд, дает преимущество на спасброски от отравления и сопротивление яду." },
    { name: "Шипы", level: 2, classes: ["Друид", "Следопыт"], desc: "Конц. 10 мин. Радиус 20 фт. Труднопроходимая местность. Существо получает 2d4 колющего урона за каждые 5 фт пути." },
    { name: "Призыв скакуна", level: 2, classes: ["Паладин"], desc: "10 мин. Призывает духа-скакуна (боевой конь, пони, лось, верблюд или мастиф) с телепатической связью на 1 милю." },
    { name: "Животное-посланник", level: 2, classes: ["Бард", "Друид", "Следопыт"], desc: "Рит. 24 часа. Маленький зверь доставляет сообщение (до 25 слов) существу, проходя до 50 миль за сутки." },
    { name: "Звериные чувства", level: 2, classes: ["Друид", "Следопыт"], desc: "Рит. Конц. 1 час. Касание согласного зверя. Вы можете видеть его глазами и слышать его ушами." },
    { name: "Гадание", level: 2, classes: ["Жрец"], desc: "Рит. Вы задаете божеству вопрос о планах на ближайшие 30 минут и получаете пророческий ответ." },
    { name: "Дубовая кожа", level: 2, classes: ["Друид", "Следопыт"], desc: "Конц. 1 час. Касание. Кожа цели становится прочной как кора. КД цели не может быть меньше 16." },
    { name: "Притворная смерть", level: 3, classes: ["Бард", "Жрец", "Друид", "Волшебник"], desc: "Рит. Касание. 1 час. Цель погружается в состояние, неотличимое от смерти, получая сопротивление почти всему урону." },
    { name: "Охранные руны", level: 3, classes: ["Бард", "Жрец", "Волшебник", "Изобретатель"], desc: "1 час. До срабатывания. Руна на поверхности (взрыв 5d8 стихией на 20 фт при спасе Ловкости или сохраненное заклинание)." },
    { name: "Крошечная хижина Леомунда", level: 3, classes: ["Бард", "Волшебник"], desc: "Рит. 1 мин. 8 часов. Полусфера радиусом 10 фт. Непроницаема снаружи, комфортна, вмещает до 9 существ." },
    { name: "Необнаружимость", level: 3, classes: ["Бард", "Следопыт", "Волшебник"], desc: "Касание. 24 часа. Защищает цель от любой магии предсказания и слежки через магические сенсоры." },
    { name: "Рост растений", level: 3, classes: ["Бард", "Друид", "Следопыт"], desc: "1 действие (радиус 100 фт, перемещение стоит 4 фт за 1 фт) или 8 часов (обогащает землю на 1 год в радиусе 1 мили)." },
    { name: "Послание", level: 3, classes: ["Бард", "Жрец", "Волшебник"], desc: "Отправляет мысленное сообщение (до 25 слов) любому существу на любом расстоянии и плане. Цель отвечает." },
    { name: "Метель", level: 3, classes: ["Друид", "Чародей", "Волшебник"], desc: "Конц. 1 мин. Цилиндр 40 фт. Лед и снег гасят огонь, делают область труднопроходимой. Спас Ловкости или падение ничком." },
    { name: "Ветряная стена", level: 3, classes: ["Друид", "Следопыт"], desc: "Конц. 1 мин. Стена ветра до 50 фт длиной. Спас Силы, 3d8 дробящего урона. Отклоняет стрелы и снаряды вверх." },
    { name: "Ослепляющая кара", level: 3, classes: ["Паладин"], desc: "Бонусное. Конц. 1 мин. След. атака оружием наносит +3d8 урона излучением, спас Телосложения или цель ослеплена." },
    { name: "Мантия крестоносца", level: 3, classes: ["Паладин"], desc: "Конц. 1 мин. Аура 30 фт вокруг вас. Все союзники наносят +1d4 урона излучением при попадании атаками оружием." },
    { name: "Голод Хадара", level: 3, classes: ["Колдун"], desc: "Конц. 1 мин. Сфера пустоты радиусом 20 фт. Враги получают 2d6 холода в начале хода и 2d6 кислоты в конце хода (спас Ловк.)." },
    { name: "Громовая стрела", level: 3, classes: ["Следопыт"], desc: "Бонусное. Конц. 1 мин. След. дальняя атака оружием наносит 4d8 молнии цели и 2d8 грома всем в 10 фт (спас Ловк.)." },
    { name: "Шквал стрел", level: 3, classes: ["Следопыт"], desc: "Конус 60 фт из копий брошенного оружия/стрелы. Спасбросок Ловкости. 3d8 урона оружием (половина при успехе)." },
    { name: "Око чародея", level: 4, classes: ["Волшебник", "Изобретатель"], desc: "Конц. 1 час. Создает невидимый парящий глаз (темное зрение 30 фт). Вы видите сквозь него и двигаете на 30 фт." },
    { name: "Потайной сундук Леомунда", level: 4, classes: ["Волшебник", "Изобретатель"], desc: "Касание. Скрывает сундук на Эфирном плане до 60 дней. Вызывается действием с помощью миниатюрной копии." },
    { name: "Верный пес Морденкайнена", level: 4, classes: ["Волшебник", "Изобретатель"], desc: "8 часов. 30 фт. Создает невидимого сторожевого пса (видит невидимое на 30 фт). Кусает врагов на 4d8 колющего урона." },
    { name: "Личное святилище Морденкайнена", level: 4, classes: ["Волшебник", "Изобретатель"], desc: "10 мин. 24 часа. Куб до 100 фт. Блокирует телепортацию, эфирный переход и предсказания внутрь зоны." },
    { name: "Упругая сфера Отилюка", level: 4, classes: ["Волшебник", "Изобретатель"], desc: "Конц. 1 мин. Спасбросок Ловкости. Заключает существо в непроницаемую светящуюся сферу, защищая от любого урона." },
    { name: "Ошеломляющая кара", level: 4, classes: ["Паладин"], desc: "Бонусное. Конц. 1 мин. След. атака оружием наносит +4d6 урона звуком. Спас Мудрости или цель ошеломлена." },
    { name: "Призыв малых элементалей", level: 4, classes: ["Друид", "Волшебник"], desc: "1 мин. Конц. 1 час. Призывает элементалей (1 шт опасности 2, 2 шт опасности 1, 4 шт опасности 1/2 или 8 шт опасности 1/4)." },
    { name: "Призыв лесных обитателей", level: 4, classes: ["Друид", "Следопыт"], desc: "1 действие. Конц. 1 час. Призывает духов фей (1 шт опасности 2, 2 шт опасности 1, 4 шт опасности 1/2 или 8 шт опасности 1/4)." },
    { name: "Защита от смерти", level: 4, classes: ["Жрец", "Паладин"], desc: "Касание. 8 часов. Первый раз, когда хиты цели опускаются до 0, они становятся равны 1. Игнорирует мгновенную смерть." },
    { name: "Цепкая лоза", level: 4, classes: ["Друид", "Следопыт"], desc: "Бонусное. Конц. 1 мин. Лоза вырастает на 30 фт. Бонусным действием каждый ход притягивает цель на 20 фт к себе (спас Ловк.)." },
    { name: "Воображаемый убийца", level: 4, classes: ["Волшебник"], desc: "Конц. 1 мин. Спас Мудрости. Цель видит иллюзию своего худшего страха: напугана и получает 4d10 психического урона каждый ход." },
    { name: "Огненный удар", level: 5, classes: ["Жрец"], desc: "Столб огня радиусом 10 фт и высотой 40 фт. Спасбросок Ловкости. 4d6 огня + 4d6 излучения (половина при успехе)." },
    { name: "Наблюдение", level: 5, classes: ["Бард", "Жрец", "Друид", "Волшебник"], desc: "10 мин. Конц. 10 мин. Спасбросок Мудрости. Создает невидимый сенсор около цели, позволяя видеть и слышать ее везде." },
    { name: "Общение с природой", level: 5, classes: ["Друид", "Следопыт"], desc: "Рит. 1 мин. Получаете знания о местности в радиусе 3 миль (водоемы, поселения, минералы, нежить, логова)." },
    { name: "Рассвет (Освящение)", level: 5, classes: ["Жрец"], desc: "24 часа. Касание. Освящает область радиусом 60 фт: блокирует исчадий и нежить, накладывая выбранный постоянный эффект." },
    { name: "Обман", level: 5, classes: ["Бард", "Волшебник"], desc: "Бонусное. Конц. 1 час. Вы становитесь невидимым, а на вашем месте возникает иллюзорный двойник, управляемый действием." },
    { name: "Изменение памяти", level: 5, classes: ["Бард", "Волшебник"], desc: "Конц. 1 мин. Спас Мудрости. Цель очарована и недееспособна. Вы можете переписать до 10 минут ее воспоминаний." },
    { name: "Ментальная связь Рэри", level: 5, classes: ["Бард", "Волшебник"], desc: "Рит. 1 час. Связывает до 8 согласных существ телепатической связью на расстоянии до 1 мили." },
    { name: "Оболочка антижизни", level: 5, classes: ["Друид"], desc: "Конц. 1 час. Барьер радиусом 10 фт вокруг вас. Не дает живым существам (кроме нежити и конструктов) подойти к вам." },
    { name: "Нашествие насекомых", level: 5, classes: ["Жрец", "Друид", "Чародей"], desc: "Конц. 10 мин. Сфера саранчи радиусом 20 фт. Спасбросок Телосложения, 4d10 колющего урона." },
    { name: "Пробуждение разума", level: 5, classes: ["Бард", "Друид"], desc: "8 часов. Касание. Дает зверю или растению Интеллект 10, способность говорить на языке и очарованность вами на 30 дней." },
    { name: "Круг телепортации", level: 5, classes: ["Бард", "Чародей", "Волшебник"], desc: "1 мин. 1 раунд. Открывает портал к постоянному кругу телепортации, сигилы которого вам известны." },
    { name: "Древесный портал", level: 5, classes: ["Друид", "Следопыт"], desc: "Конц. 1 мин. За 5 фт движения вы можете войти в живое дерево и выйти из другого дерева того же вида в 500 фт." },
    { name: "Изгоняющая кара", level: 5, classes: ["Паладин"], desc: "Бонусное. Конц. 1 мин. След. атака оружием наносит +5d10 силового урона. Если у цели осталось 50 хитов или меньше, она изгоняется на свой родной план." },
    { name: "Круг силы", level: 5, classes: ["Паладин"], desc: "Конц. 10 мин. Аура 30 фт вокруг вас. Союзники получают преимущество на спасброски от магии и не получают урона при успешном спасе." },
    { name: "Общение", level: 5, classes: ["Жрец"], desc: "Рит. 1 мин. Вы задаете божеству до трех вопросов, на которые можно ответить «да», «нет» или «неизвестно»." },
    { name: "Связь с иным планом", level: 5, classes: ["Колдун", "Волшебник"], desc: "Рит. 1 мин. Спас Интеллекта СЛ 15 (провал: 3d6 урона и безумие до отдыха). Успех: задаете существу с иного плана до 5 вопросов («да»/«нет»)." },
    { name: "Заражение", level: 5, classes: ["Жрец", "Друид"], desc: "Атака касанием. Цель заражается одной из болезней (ослепление, истощение, оцепенение, слабость) при провале трех спасов Тела." },
    { name: "Сотворение", level: 5, classes: ["Чародей", "Волшебник", "Изобретатель"], desc: "1 мин. Создает немагический предмет из растительной ткани, камня, металла или драгоценностей на срок от нескольких часов до суток." },
    { name: "Разрушительная волна", level: 5, classes: ["Паладин"], desc: "Радиус 30 фт вокруг вас. Враги делают спас Телосложения: получают 5d6 звукового + 5d6 излучением/некротического урона и падают ничком." },
    { name: "Рассеять зло и добро", level: 5, classes: ["Жрец", "Паладин"], desc: "Конц. 1 мин. Целестиалы, элементали, феи, исчадия и нежить имеют помеху на атаки по вам. Вы можете изгнать существо на родной план атакой касанием." },
    { name: "Зарок (Гейс)", level: 5, classes: ["Бард", "Жрец", "Друид", "Паладин", "Волшебник"], desc: "1 мин. 30 дней. Спас Мудрости. Цель обязана исполнять вашу команду. Нарушение наносит 5d10 психического урона раз в день." },
    { name: "Знание легенд", level: 5, classes: ["Бард", "Жрец", "Волшебник"], desc: "10 мин. Вы называете известную персону, место или предмет легендарной важности и получаете краткую сводку преданий о них." },
    { name: "Создание прохода", level: 5, classes: ["Волшебник"], desc: "1 час. Проделывает проход шириной 5 фт, высотой 8 фт и глубиной до 20 фт в деревянной, гипсовой или каменной стене." },
    { name: "Планарные узы", level: 5, classes: ["Бард", "Жрец", "Друид", "Волшебник"], desc: "1 час. 24 часа. Спас Харизмы. Привязывает целестиала, элементаля, фею или исчадие к вашей службе." },
    { name: "Притворство", level: 5, classes: ["Бард", "Чародей", "Волшебник"], desc: "8 часов. Изменяет иллюзией внешний вид любого числа выбранных существ в пределах 30 фт." },
    { name: "Быстрый колчан", level: 5, classes: ["Следопыт"], desc: "Бонусное. Конц. 1 мин. Ваш колчан порождает бесконечные стрелы. Бонусным действием каждый ход вы можете совершить две дальние атаки оружием." },
    { name: "Дезинтеграция", level: 6, classes: ["Чародей", "Волшебник"], desc: "Луч в цель в 60 фт. Спасбросок Ловкости. 10d6+40 силового урона. Если цель убита этим уроном, она превращается в серую пыль." },
    { name: "Сфера неуязвимости", level: 6, classes: ["Чародей", "Волшебник"], desc: "Конц. 1 мин. Сфера радиусом 10 фт вокруг вас. Полностью блокирует заклинания 5 круга и ниже, нацеленные снаружи." },
    { name: "Запрет", level: 6, classes: ["Жрец"], desc: "Рит. 10 мин. До 24 часов. Защищает площадь до 40 000 кв. фт от телепортации и наносит 5d10 урона излучением чужакам." },
    { name: "Охранные стражи", level: 6, classes: ["Бард", "Волшебник"], desc: "10 мин. 24 часа. Защищает здание (туман в коридорах, запертые двери, паутина на лестницах и внушение на развилках)." },
    { name: "Поиск пути", level: 6, classes: ["Бард", "Жрец", "Друид"], desc: "Конц. 1 день. Позволяет узнать кратчайший и самый прямой физический путь к известному вам фиксированному месту." },
    { name: "Перемещение через растения", level: 6, classes: ["Друид"], desc: "1 раунд. Открывает проход сквозь крупное растение к любому другому растению того же вида на том же плане." },
    { name: "Стена клинков", level: 6, classes: ["Жрец"], desc: "Конц. 10 мин. Стена крутящихся лезвий до 100 фт длиной. Спас Ловкости. 6d10 рубящего урона при входе или начале хода." },
    { name: "Стена шипов", level: 6, classes: ["Друид"], desc: "Конц. 10 мин. Стена колючих лоз до 60 фт длиной. Спас Ловк. 7d8 колющего урона при появлении. Движение сквозь стену стоит 4 фт за 1 фт." },
    { name: "Сотворение нежити", level: 6, classes: ["Жрец", "Колдун", "Волшебник"], desc: "1 мин. Касание до 3 трупов. Поднимает их в виде упырей под вашим контролем на 24 часа." },
    { name: "Призыв фей", level: 6, classes: ["Друид", "Колдун"], desc: "1 мин. Конц. 1 час. Призывает могущественного духа феи (опасности 6 или ниже), подчиняющегося вам." },
    { name: "Предосторожность", level: 6, classes: ["Волшебник"], desc: "10 мин. 10 дней. Привязывает к вам заклинание 5 круга или ниже, которое автоматически срабатывает при описанном условии." },
    { name: "Мгновенный призыв Дромиджа", level: 6, classes: ["Волшебник"], desc: "Рит. Касание предмета. Помечает предмет сапфиром. Действием вы можете раздавить сапфир и мгновенно телепортировать предмет в руку." },
    { name: "Волшебный сосуд", level: 6, classes: ["Волшебник"], desc: "1 мин. До рассеивания. Ваша душа перемещается в драгоценный сосуд, оставляя тело мертвым. Из сосуда вы можете вселяться в чужие тела (спас Харизмы)." },
    { name: "Изменение формы земли", level: 6, classes: ["Друид", "Чародей", "Волшебник"], desc: "Конц. До 2 часов. Вы перекапываете и трансформируете земляные валы, рвы, канавы и возвышенности в области 40 фт каждые 10 минут." },
    { name: "Ледяная сфера Отилюка", level: 6, classes: ["Волшебник"], desc: "Сфера холода радиусом 60 фт в 300 фт. Спас Ловкости. 10d6 урона холодом и замораживает воду на площади 100 кв. фт толщиной 6 дюймов." },
    { name: "Неудержимая пляска Отто", level: 6, classes: ["Бард", "Волшебник"], desc: "Конц. 1 мин. Дистанция 30 фт. Цель мгновенно пускается в безудержную пляску (лишается перемещения, помехи на атаки/спасы, враги имеют преимущество по ней)." },
    { name: "Планарный союзник", level: 6, classes: ["Жрец"], desc: "10 мин. Вы призываете небесного жителя, элементаля или исчадие для выполнения задачи в обмен на плату сокровищами или услугой." },
    { name: "Запрограммированная иллюзия", level: 6, classes: ["Бард", "Волшебник"], desc: "1 раунд. До рассеивания. Создает иллюзию события или существа (до 5 минут), которая активируется при срабатывании условия." },
    { name: "Замедленный огненный шар", level: 7, classes: ["Чародей", "Волшебник"], desc: "Конц. До 1 мин. Желтая бусина накапливает мощь: 12d6 огня + 1d6 за каждый раунд концентрации (до +10d6). Спас Ловкости." },
    { name: "Воскрешение", level: 7, classes: ["Бард", "Жрец"], desc: "1 час. Касание. Возвращает к жизни существо, умершее не более века назад (восстанавливает все хиты, отращивает конечности)." },
    { name: "Силовая клетка", level: 7, classes: ["Бард", "Колдун", "Волшебник"], desc: "1 час. Создает невидимую нерушимую клетку 20 фт или ящик 10 фт из чистой силы. Не пропускает заклинания и телепортацию." },
    { name: "Мираж", level: 7, classes: ["Бард", "Друид", "Волшебник"], desc: "10 мин. 10 дней. Преобразует местность до 1 кв. мили, создавая тактильно осязаемую иллюзию холмов, строений, рек и пропастей." },
    { name: "Символ", level: 7, classes: ["Бард", "Жрец", "Волшебник"], desc: "1 мин. До срабатывания. Наносит скрытый символ (Смерть 10d10 некротикой, Раздор, Страх, Сон, Ошеломление и т.д.)." },
    { name: "Меч Морденкайнена", level: 7, classes: ["Бард", "Волшебник"], desc: "Бонусное. Конц. 1 мин. Парящий силовой меч. Атака заклинанием наносит 3d10 силового урона. Перемещается на 20 фт бонусным действием." },
    { name: "Призыв небожителя", level: 7, classes: ["Жрец"], desc: "1 мин. Конц. 1 час. Призывает небожителя опасности 4 или ниже (куатль или пегас), который подчиняется вашим командам." },
    { name: "Бесплотность", level: 7, classes: ["Бард", "Жрец", "Колдун", "Волшебник"], desc: "8 часов. Вы переходите на Эфирный план и можете перемещаться сквозь стены и объекты материального мира." },
    { name: "Симулякр", level: 7, classes: ["Волшебник"], desc: "12 часов. Касание. Создает иллюзорную копию зверя или гуманоида из снега и льда с половиной хитов оригинала и его заклинаниями." },
    { name: "Зажигательное облако", level: 8, classes: ["Чародей", "Волшебник"], desc: "Конц. 1 мин. Сфера раскаленного белого дыма радиусом 20 фт. Спас Ловкости. 10d8 урона огнем. Движется от вас на 10 фт/раунд." },
    { name: "Слово силы: Оглушение", level: 8, classes: ["Бард", "Чародей", "Колдун", "Волшебник"], desc: "60 фт. Существо с 150 хитами или меньше мгновенно становится ошеломленным (без спасброска)." },
    { name: "Клон", level: 8, classes: ["Волшебник"], desc: "1 час. Выращивает инертного двойника существа в сосуде за 120 дней. При смерти оригинала душа переселяется в тело клона." },
    { name: "Цунами", level: 8, classes: ["Друид"], desc: "1 мин. Конц. До 6 раундов. Стена воды высотой 300 фт и длиной 300 фт. Спас Силы, 6d10 дробящего урона, смывает существ на 50 фт." },
    { name: "Формы животных", level: 8, classes: ["Друид"], desc: "Конц. 24 часа. Превращает любое число согласных существ в 30 фт в зверей опасности 4 или ниже с полным запасом их хитов." },
    { name: "Антипатия/Симпатия", level: 8, classes: ["Бард", "Друид", "Волшебник"], desc: "1 час. 10 дней. Накладывает на объект непреодолимое влечение или отвращение для определенного вида существ (спас Мудрости)." },
    { name: "Сладкоречие", level: 8, classes: ["Бард", "Колдун"], desc: "1 час. Если вы выбрасываете на кубике d20 меньше 15 при проверке Харизмы (Обман или Убеждение), результат считается равным 15." },
    { name: "Защита разума", level: 8, classes: ["Бард", "Волшебник"], desc: "24 часа. Касание. Цель получает иммунитет к психическому урону, чтению мыслей, предсказаниям и эффектам очарования." },
    { name: "Остановка времени", level: 9, classes: ["Чародей", "Волшебник"], desc: "Мгновенно останавливает время для всех, кроме вас, на 1d4+1 раундов. Вы можете перемещаться и колдовать свободно." },
    { name: "Смена облика", level: 9, classes: ["Друид", "Волшебник"], desc: "Конц. 1 час. Превращаетесь в любое существо опасности равной вашему уровню или ниже. Форму можно менять действием каждый ход." },
    { name: "Странность", level: 9, classes: ["Волшебник"], desc: "Конц. 1 мин. Сфера 30 фт. Спас Мудрости. Цели видят худшие кошмары: испуганы и получают 4d10 психического урона каждый ход." },
    { name: "Шторм возмездия", level: 9, classes: ["Друид"], desc: "Конц. 1 мин. Радиус 360 фт. Каждый раунд новый катаклизм: кислотный дождь 2d6, молнии 10d6, град 2d6, ледяной ветер 1d6." }
];
